// Conversion offer logic: when a lead is detected, present a time-limited offer to convert to paid.
// This module hooks into the lead capture flow and triggers a conversion offer.

const offers = [
  { id: 'early_bird', discount: 0.2, durationHours: 24, label: 'Early Bird 20% off' },
  { id: 'volume', discount: 0.15, durationHours: 48, label: 'Volume discount 15% off' },
  { id: 'loyalty', discount: 0.1, durationHours: 72, label: 'Loyalty discount 10% off' }
];

function getOfferForLead(lead) {
  // Simple rotation based on lead count
  const index = lead.id % offers.length;
  return offers[index];
}

function presentOffer(lead) {
  const offer = getOfferForLead(lead);
  // In production, this would push to a queue or update a database
  console.log(`[ConversionOffer] Presenting offer ${offer.id} to lead ${lead.id}`);
  return { success: true, offer };
}

module.exports = { presentOffer, offers };
